head.script:
    requires("uiplugin.popup");
	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};


scwin.trigger1_onclick = function(e) {
	var rowJSON = {
		"addr": "서울시",
		"name": "손예진",
		"rowStatus": "R"
	};
	var dataObject={
		type : "json",  
		data : rowJSON,  
		name : "rowObj"  

};
	var options = {
		type : "browserPopup",
		id : "testpopup",
		width : "800px",
		height : "500px",
		modal : true,
		useControl : true,
		controls:{
						minimize : true,
						maximize : true,
						close : false
					},
		dataObject : dataObject

	};

	$p.openPopup("popup_openPopup_getParameter_WESE-282_(WSQ-5274)_popup.xml" , options);
};




